import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.DWfJTVRq.js";const y=JSON.parse('{"title":"Encryption","description":"This page explains how DaruDB encrypts and authenticates a database file: the page cipher and how it is chosen, the data key and how a key or a password wraps…","frontmatter":{"title":"Encryption","order":6,"prev":{"text":"Locking","link":"/engine/locking"},"next":{"text":"API","link":"/api/"}},"headers":[{"level":2,"title":"What is encrypted","slug":"what-is-encrypted","link":"#what-is-encrypted","children":[]},{"level":2,"title":"Pages","slug":"pages","link":"#pages","children":[{"level":3,"title":"Which cipher","slug":"which-cipher","link":"#which-cipher","children":[]}]},{"level":2,"title":"The data key and the key block","slug":"the-data-key-and-the-key-block","link":"#the-data-key-and-the-key-block","children":[{"level":3,"title":"Changing the key or the password","slug":"changing-the-key-or-the-password","link":"#changing-the-key-or-the-password","children":[]}]},{"level":2,"title":"Passwords","slug":"passwords","link":"#passwords","children":[]},{"level":2,"title":"Commit records","slug":"commit-records","link":"#commit-records","children":[]},{"level":2,"title":"What stays visible","slug":"what-stays-visible","link":"#what-stays-visible","children":[]},{"level":2,"title":"Keys in memory","slug":"keys-in-memory","link":"#keys-in-memory","children":[]}],"relativePath":"engine/encryption.md","filePath":"en/engine/encryption.md","lastUpdated":1791000973000}'),i={name:"engine/encryption.md"};function r(n,e,h,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h1><p>This page explains how DaruDB encrypts and authenticates a database file: the page cipher and how it is chosen, the data key and how a key or a password wraps it, the MAC on commit records, and what an encrypted file still shows.</p><p>The specification is the &quot;Encryption&quot; section of <a href="https://github.com/jooy2/darudb/blob/main/design/file-format.md#encryption" target="_blank" rel="noreferrer">design/file-format.md</a> in the repository. <a href="./../guide/encryption">Encryption</a> shows how to open, create and rekey an encrypted database.</p><h2 id="what-is-encrypted" tabindex="-1">What is encrypted <a class="header-anchor" href="#what-is-encrypted" aria-label="Permalink to &quot;What is encrypted&quot;">​</a></h2><p>A database created with a key or a password is encrypted for its whole life: every page but the header, and so every key, every value and every tree name. Every page is also authenticated, and so is every commit record in the header, so a changed byte is reported as <code>CORRUPTED</code> rather than read.</p><p>A plain database stays plain. It cannot be encrypted in place: its data has to be copied into a new database created with a key or a password.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><p>Each page is encrypted under the file&#39;s data key with an authenticated cipher:</p><ul><li><strong>The nonce</strong> is 24 random bytes, drawn fresh every time the page is written, and stored in the first 24 bytes of the page, the field every page reserves.</li><li><strong>The associated data</strong> is the page number, which binds the ciphertext to its place in the file.</li><li><strong>The tag</strong> of 16 bytes is the page&#39;s check. It is stored at the end of the page and in the pointer that leads to the page.</li></ul><p>Because the tag is stored in the parent too, someone who can write the file cannot put back an older, validly encrypted version of a page: its tag would not match the one its parent records. A large value&#39;s run check is a hash over its pages&#39; tags, which carries the same protection to its pages.</p><h3 id="which-cipher" tabindex="-1">Which cipher <a class="header-anchor" href="#which-cipher" aria-label="Permalink to &quot;Which cipher&quot;">​</a></h3><p>A file uses one of two ciphers, XAES-256-GCM or XChaCha20-Poly1305. Both take a 24-byte nonce and give a 16-byte tag, so a page has the same layout under either.</p><p>A new encrypted file gets XAES-256-GCM when the machine that creates it has AES and carry-less multiplication instructions, and XChaCha20-Poly1305 otherwise, because each is several times faster than the other on the processors it suits. On one Apple silicon machine, 4 KiB pages encrypt at about 3.0 GB/s with XAES-256-GCM and 0.7 GB/s with XChaCha20-Poly1305; on software implementations alone the order reverses, at 0.13 and 0.32 GB/s. Old 32-bit ARM phones and some small ARM boards lack the instructions, and there the choice keeps the file fast.</p><p>The application does not choose. The header records the cipher, a file keeps it for life, and any machine opens a file of either kind, only more slowly where the processor does not suit its cipher.</p><p>A random 192-bit nonce is safe for any number of page writes under one key. Plain AES-256-GCM has a 96-bit nonce, which makes random nonces unsafe after about 2^32 page writes under one key, and a counter is hard to keep unique across several writer processes and crashes. XAES-256-GCM solves that by deriving a fresh AES-256-GCM key from the first half of each 24-byte nonce.</p><h2 id="the-data-key-and-the-key-block" tabindex="-1">The data key and the key block <a class="header-anchor" href="#the-data-key-and-the-key-block" aria-label="Permalink to &quot;The data key and the key block&quot;">​</a></h2><p>The pages are encrypted under a data key: 32 random bytes, generated when the file is created. The data key is stored wrapped, in a key block that every commit record carries.</p><ul><li><strong>The key that wraps it</strong> is the caller&#39;s 32-byte key, or the Argon2id hash of the caller&#39;s password, under a salt and a cost stored in the key block.</li><li><strong>It is wrapped with XChaCha20-Poly1305</strong>, with the file&#39;s id as associated data, so a key block copied into another file does not unwrap there.</li><li><strong>Opening</strong> tries the key or password on the key block of each commit record whose check matches, newest first, and uses the first that unwraps. The records share one data key, so which one unwraps it does not matter. A wrong key or password fails every wrapping tag, and opening fails with <code>WRONG_KEY</code>. An encrypted file opened without a key or password fails with <code>KEY_REQUIRED</code>, and a plain file opened with one fails with <code>INVALID_ARGUMENT</code>.</li></ul><h3 id="changing-the-key-or-the-password" tabindex="-1">Changing the key or the password <a class="header-anchor" href="#changing-the-key-or-the-password" aria-label="Permalink to &quot;Changing the key or the password&quot;">​</a></h3><p>Changing the key or the password writes a new key block and re-encrypts no page, so it takes the same time whatever the size of the file. It is a sync commit with the new key block, followed by empty sync commits until no slot holds the old one: three commits in all when nothing else commits in between. Every commit copies the key block of the one before it, which is how the new one reaches the other slots. Until then, the old key still opens the file; once the call returns, it no longer does. In Rust the calls are <code>Database::set_key</code> and <code>Database::set_password</code>, and in Node.js <code>setKey</code> and <code>setPassword</code>.</p><p>The data key itself stays the same for the life of the file. A backup and a salvage keep it too, since the new file takes the old one&#39;s key block, so the key or password that opens the file opens the copy.</p><h2 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to &quot;Passwords&quot;">​</a></h2><p>A password becomes a key through Argon2id, which is memory-hard: that is what makes guessing passwords on graphics processors expensive. The default cost is 19 MiB of memory, 2 iterations and 1 lane, the lowest Argon2id setting in the OWASP password storage guidance, which takes tens of milliseconds on a current computer. The memory is what decides it, because a mobile app extension may be allowed little more than that for its whole process.</p><p>The cost is stored in each key block, so an application can ask for more when it creates a file or changes its password, <code>OpenOptions::password_hashing</code> in Rust and <code>passwordHashing</code> in Node.js, without a change to the format. Opening a file always takes the cost it was made with. A key block that asks for more than 1 GiB of memory, 1024 iterations or 64 lanes is refused as <code>CORRUPTED</code> before anything is hashed, since the hash allocates its memory at once.</p><h2 id="commit-records" tabindex="-1">Commit records <a class="header-anchor" href="#commit-records" aria-label="Permalink to &quot;Commit records&quot;">​</a></h2><p>The header stays plain, and each page&#39;s tag sits in the clear in its parent as well as in the page. Without a key of its own, a commit record could therefore be assembled by anyone who can write the file, from pages that are already there: the catalog of one commit with the free tree of another, say. No key holder committed that state, and its trees would disagree about which pages are in use, so the next commit would overwrite pages still in use.</p><p>Each record of an encrypted file therefore carries a MAC: keyed BLAKE2b with a 16-byte output, under a key derived from the data key, over the file id, the slot number and the record&#39;s fields and key block. Recovery never adopts a record whose MAC fails, and a process that reads a record another process wrote checks its MAC as well. BLAKE2b is in the build for Argon2id already, and a MAC of its own keeps the record independent of the page cipher.</p><h2 id="what-stays-visible" tabindex="-1">What stays visible <a class="header-anchor" href="#what-stays-visible" aria-label="Permalink to &quot;What stays visible&quot;">​</a></h2><p>The header page is plain, so an encrypted file still shows its page size, its file id, its cipher, its transaction ids, its page count, and so its size, and the page numbers of its tree roots. Everything inside a page is encrypted.</p><p>Replacing the whole file, or the header page alone, with an older copy of itself cannot be detected from inside the file, because the older records are genuine. An application that needs to detect that has to keep the newest transaction id somewhere else; in Rust, <code>ReadTransaction::commit_id</code> reads it.</p><h2 id="keys-in-memory" tabindex="-1">Keys in memory <a class="header-anchor" href="#keys-in-memory" aria-label="Permalink to &quot;Keys in memory&quot;">​</a></h2><p>The engine keeps keys in buffers that are wiped when they are dropped, and the cipher wipes its own copy. That narrows how long a key sits in memory, but it cannot rule out a copy the compiler or the operating system made. The Node.js package copies the key or password it is given into buffers of its own, and fills them with zeros once the engine has its copy, which it takes when the call is made. A password passed as a JavaScript string stays in memory until the garbage collector reclaims it, so pass a <code>Uint8Array</code> to be able to wipe it.</p><p>Keep the key where it cannot be lost, such as the operating system&#39;s keystore. Without it, the data cannot be read.</p>',33)])])}const w=t(i,[["render",r]]);export{y as __pageData,w as default};
